			return scoreModifier * scoreInput;
		case ScoreCalculationMethod.TwoPowX:
			return Mathf.RoundToInt(Mathf.Pow(2f, (float)scoreModifier));
		case ScoreCalculationMethod.XSquared:
			return Mathf.RoundToInt(Mathf.Pow((float)scoreModifier, 2f));
		default:
			return scoreModifier;
		}
	}

