		dictionary.Add("AnalyticsEnabled", PlayerPrefs.GetInt("AnalyticsEnabled", -1));
		dictionary.Add("AnalyticsOptInShown", PlayerPrefs.GetInt("AnalyticsOptInShown", -1));
