			{
				while (enumerator3.MoveNext())
				{
					LeaderboardType leaderboard = enumerator3.Current;
					dictionary.Add(leaderboard.GetPlayerPrefsScoreKey(false), PlayerPrefs.GetInt(leaderboard.GetPlayerPrefsScoreKey(false), -1));
					IEnumerable<string> enumerable;
					if (leaderboard.IsMonthlyLeaderboard)
					{
						enumerable = Enumerable.Select<string, string>(leaderboard.GetAllSeasonIds(LeaderboardManager.FirstSeasonDate, utcNow), (string seasonId) => leaderboard.GetLeaderboardId(seasonId));
					}
					else
					{
						enumerable = new string[] { leaderboard.GetLeaderboardId() };
					}
					foreach (string text2 in enumerable)
					{
						string text3 = text2 + "_steamPendingScore";
						string text4 = text2 + "_steamPendingDetails";
						int @int = PlayerPrefs.GetInt(text3, 0);
						if (@int > 0)
						{
							dictionary[text3] = @int;
							string @string = PlayerPrefs.GetString(text4, "");
							if (!string.IsNullOrEmpty(@string))
							{
								dictionary2[text4] = @string;
							}
						}
					}
				}
			}
		}
		Debug.Log("Delete all Player Prefs, apart from " + ListHelper.ListDebugString<string>(Enumerable.ToList<string>(dictionary.Keys), ", "));
		PlayerPrefs.DeleteAll();
		foreach (KeyValuePair<string, int> keyValuePair in dictionary)
		{
			if (keyValuePair.Value != -1)
			{
				PlayerPrefs.SetInt(keyValuePair.Key, keyValuePair.Value);
			}
		}
		foreach (KeyValuePair<string, string> keyValuePair2 in dictionary2)
		{
			PlayerPrefs.SetString(keyValuePair2.Key, keyValuePair2.Value);
		}
		if (Application.isEditor)
		{
			this.sessionQuestManager.BuildReset(null, null);
		}
		this.rewardLibrary.Setup();
		this.sessionQuestManager.Setup();
	}

