		{
			saveGameData_ = (SaveGameData_003)SaveGameConverter.UpgradeSaveGame(JsonLoader.LoadJsonFromDataLocation<SaveGameData_001>(Path.Combine("Saves", saveGameName) + ".json", DataLocation.PersistentDataPath));
			base.StartCoroutine(this.SetupLoadedGame(saveGameData_));
			return;
		}
		string text = Path.Combine("Saves", saveGameName);
		SuccessStatus successStatus;
		SaveGameData saveGameData = BinarySaveLoad.LoadFromBinary<SaveGameData>(text, out successStatus);
		if (saveGameData == null)
		{
			this.SetupNewGame();
			return;
		}
		saveGameData_ = (SaveGameData_003)SaveGameConverter.LoadCurrentVersionSavegame(saveGameData.version, text);
		base.StartCoroutine(this.SetupLoadedGame(saveGameData_));
	}

